def zfzh(s):
    c = ''
    for ch in s:
        if "9">=ch>= "0":
            c+=str(int(ch)+1)
        elif "z">=ch>= "a":
            c+= chr(ord(ch)- ord("a")+ord("A"))
    return c
s = 'hzag-21-8'
print(zfzh(s))

def peach(day):
    if day==1:
        return 1
    return (peach(day-1) + 1)*2
s=peach(5)
print('一共有%d只桃子'%(s))

def lcm(s,m,n):
    if s%n==0:
        return s
    else:
        return lcm(s+m,m,n)
a=int(input('请输入第1个数：'))
b=int(input('请输入第2个数：'))
c=lcm(a,a,b)
print('{}和{}的最小公倍数是{}'.format(a,b,c))

